style.css:
@-moz-document domain("youtube.com") {
:root,
  html[dark],
  html {
    --neon-bg: #07050f;
    --neon-panel: #0f0b1f;
    --neon-panel-2: #171030;
    --neon-cyan: #00f0ff;
    --neon-pink: #ff2bd6;
    --neon-violet: #8a5cff;
    --neon-text: #eaf6ff;
    --neon-dim: #9aa6c9;

    /* Override YouTube's own design tokens */
    --yt-spec-base-background: var(--neon-bg) !important;
    --yt-spec-raised-background: var(--neon-panel) !important;
    --yt-spec-menu-background: var(--neon-panel) !important;
    --yt-spec-general-background-a: var(--neon-bg) !important;
    --yt-spec-general-background-b: var(--neon-panel) !important;
    --yt-spec-general-background-c: var(--neon-panel-2) !important;
    --yt-spec-text-primary: var(--neon-text) !important;
    --yt-spec-text-secondary: var(--neon-dim) !important;
    --yt-spec-call-to-action: var(--neon-cyan) !important;
    --yt-spec-brand-link-text: var(--neon-cyan) !important;
    --yt-spec-static-brand-red: var(--neon-pink) !important;
    --yt-spec-themed-blue: var(--neon-cyan) !important;
    --yt-spec-10-percent-layer: rgba(0, 240, 255, 0.18) !important;
  }

  /* Page background with a soft neon haze */
  html, body, ytd-app {
    background:
      radial-gradient(900px 500px at 8% -10%, rgba(255, 43, 214, 0.14), transparent 60%),
      radial-gradient(900px 500px at 100% 0%, rgba(0, 240, 255, 0.12), transparent 60%),
      var(--neon-bg) !important;
    color: var(--neon-text) !important;
  }

  /* Top bar */
  #masthead-container ytd-masthead,
  #masthead-container #background {
    background: rgba(7, 5, 15, 0.82) !important;
    backdrop-filter: blur(14px);
    border-bottom: 1px solid rgba(0, 240, 255, 0.35);
    box-shadow: 0 0 18px rgba(0, 240, 255, 0.25);
  }

  /* Logo glow */
  ytd-topbar-logo-renderer #logo-icon {
    filter: hue-rotate(290deg) saturate(2) drop-shadow(0 0 6px var(--neon-pink));
  }

  /* Search box */
  yt-searchbox .ytSearchboxComponentInputBox,
  #search-input.ytd-searchbox,
  form.ytd-searchbox {
    background: var(--neon-panel) !important;
    border-color: rgba(0, 240, 255, 0.45) !important;
    box-shadow: 0 0 10px rgba(0, 240, 255, 0.25) inset;
    transition: box-shadow 0.2s, border-color 0.2s;
  }
  yt-searchbox:focus-within .ytSearchboxComponentInputBox,
  ytd-searchbox:focus-within form.ytd-searchbox {
    border-color: var(--neon-cyan) !important;
    box-shadow: 0 0 14px var(--neon-cyan), 0 0 0 1px var(--neon-cyan) inset;
  }
  button.ytSearchboxComponentSearchButton,
  #search-icon-legacy {
    background: linear-gradient(135deg, var(--neon-violet), var(--neon-pink)) !important;
    border-color: transparent !important;
  }

  /* Sidebar */
  tp-yt-app-drawer,
  #guide-content,
  ytd-mini-guide-renderer {
    background: var(--neon-bg) !important;
  }
  ytd-guide-entry-renderer[active] a,
  ytd-guide-entry-renderer a:hover {
    background: rgba(138, 92, 255, 0.18) !important;
    box-shadow: inset 3px 0 0 var(--neon-cyan);
    border-radius: 10px;
  }

  /* Category chips */
  yt-chip-cloud-chip-renderer,
  yt-chip-cloud-chip-renderer #chip-container {
    background: var(--neon-panel) !important;
    border: 1px solid rgba(138, 92, 255, 0.5) !important;
    color: var(--neon-text) !important;
    transition: box-shadow 0.2s, border-color 0.2s;
  }
  yt-chip-cloud-chip-renderer:hover {
    border-color: var(--neon-cyan) !important;
    box-shadow: 0 0 10px rgba(0, 240, 255, 0.55);
  }
  yt-chip-cloud-chip-renderer[chip-style="STYLE_DEFAULT"][selected],
  yt-chip-cloud-chip-renderer[selected] #chip-container {
    background: linear-gradient(135deg, var(--neon-cyan), var(--neon-violet)) !important;
    color: #07050f !important;
    border-color: transparent !important;
    box-shadow: 0 0 14px rgba(0, 240, 255, 0.7);
  }

  /* Video thumbnails */
  ytd-rich-item-renderer ytd-thumbnail,
  ytd-compact-video-renderer ytd-thumbnail,
  ytd-video-renderer ytd-thumbnail,
  yt-thumbnail-view-model,
  a.ytd-thumbnail {
    border-radius: 12px !important;
    transition: box-shadow 0.25s, transform 0.25s;
  }
  ytd-rich-item-renderer:hover ytd-thumbnail,
  ytd-compact-video-renderer:hover ytd-thumbnail,
  ytd-video-renderer:hover ytd-thumbnail,
  ytd-rich-item-renderer:hover yt-thumbnail-view-model {
    box-shadow: 0 0 0 1px var(--neon-cyan), 0 0 22px rgba(0, 240, 255, 0.55),
                0 0 40px rgba(255, 43, 214, 0.25);
    transform: translateY(-2px);
  }

  /* Titles */
  #video-title,
  h3.ytd-rich-grid-media {
    color: var(--neon-text) !important;
  }
  a#video-title:hover {
    color: var(--neon-cyan) !important;
    text-shadow: 0 0 8px rgba(0, 240, 255, 0.6);
  }

  /* Watch page */
  ytd-watch-flexy #player,
  #movie_player,
  .html5-video-player {
    border-radius: 14px;
  }
  ytd-watch-flexy #player-container-outer {
    box-shadow: 0 0 30px rgba(138, 92, 255, 0.45), 0 0 70px rgba(255, 43, 214, 0.18);
    border-radius: 14px;
  }

  /* Progress bar and scrubber */
  .ytp-play-progress,
  .ytp-swatch-background-color {
    background: linear-gradient(90deg, var(--neon-cyan), var(--neon-pink)) !important;
    box-shadow: 0 0 8px var(--neon-pink);
  }
  .ytp-scrubber-button {
    background: var(--neon-cyan) !important;
    box-shadow: 0 0 10px var(--neon-cyan);
  }

  /* Subscribe + action buttons */
  ytd-subscribe-button-renderer yt-button-shape button,
  .yt-spec-button-shape-next--filled.yt-spec-button-shape-next--call-to-action,
  .yt-spec-button-shape-next--mono.yt-spec-button-shape-next--filled {
    background: linear-gradient(135deg, var(--neon-violet), var(--neon-pink)) !important;
    color: #fff !important;
    box-shadow: 0 0 14px rgba(255, 43, 214, 0.55);
  }
  .yt-spec-button-shape-next--tonal,
  yt-button-view-model button,
  segmented-like-dislike-button-view-model button {
    background: var(--neon-panel-2) !important;
    color: var(--neon-text) !important;
    border: 1px solid rgba(0, 240, 255, 0.25);
    transition: box-shadow 0.2s, border-color 0.2s;
  }
  .yt-spec-button-shape-next--tonal:hover,
  yt-button-view-model button:hover {
    border-color: var(--neon-cyan);
    box-shadow: 0 0 10px rgba(0, 240, 255, 0.5);
  }

  /* Comments + description panels */
  ytd-comments,
  #description.ytd-watch-metadata,
  ytd-engagement-panel-section-list-renderer,
  ytd-comment-view-model {
    background: transparent !important;
  }
  #description.ytd-watch-metadata {
    background: var(--neon-panel) !important;
    border: 1px solid rgba(138, 92, 255, 0.35);
    border-radius: 12px;
  }

  /* Links and hashtags */
  a.yt-simple-endpoint[href^="/hashtag"],
  .yt-core-attributed-string__link {
    color: var(--neon-cyan) !important;
  }

  /* Menus and popups */
  ytd-popup-container tp-yt-paper-dialog,
  ytd-menu-popup-renderer,
  tp-yt-iron-dropdown .ytd-menu-popup-renderer {
    background: var(--neon-panel) !important;
    border: 1px solid rgba(0, 240, 255, 0.4);
    box-shadow: 0 0 22px rgba(0, 240, 255, 0.3);
    border-radius: 12px;
  }

  /* Scrollbar */
  ::-webkit-scrollbar { width: 10px; height: 10px; }
  ::-webkit-scrollbar-track { background: var(--neon-bg); }
  ::-webkit-scrollbar-thumb {
    background: linear-gradient(var(--neon-violet), var(--neon-pink));
    border-radius: 10px;
  }

  /* Text selection */
  ::selection {
    background: var(--neon-pink);
    color: #fff;
  }

  /* Respect reduced-motion settings */
  @media (prefers-reduced-motion: reduce) {
    * { transition: none !important; }
  }
}
